const input = $json || {};
return [{
  json: {
    ...input,
    __config: {
      TELNYX_API_KEY: 'PASTE_FULL_TELNYX_API_KEY_HERE',
      TELNYX_CONNECTION_ID: '2904363020387878017',
      FROM_NUMBER_POOL: ['+12146460598', '+12015026864'],
      TRANSFER_TO_NUMBER: 'sip:userprasidha13243@sip.telnyx.com',
      MAX_CONCURRENT_CALLS: 3,
      MAX_ATTEMPTS_PER_LEAD: 5,
      COOLDOWN_MINUTES: 60,
      WEBHOOK_TOKEN: 'telnyx-dialer-9f2c7e4b1a6d3c8e',
      DEBUG_MODE: true,
      TELNYX_API_BASE_URL: 'https://api.telnyx.com/v2',
      WEBHOOK_BASE_URL: 'https://n8n.prasidha.me',
      AMD_MODE: 'premium',
      TRANSFER_ON_NOT_SURE: false,
      WEBHOOK_PATH: 'telnyx-power-dialer'
    }
  }
}];

const root = $json || {};
const cfg = root.__config || {};
const body = root.body ?? root;
const headers = root.headers || {};
const query = root.query || {};
const event = body.data || {};
const payload = event.payload || {};
const token = query.token || '';
const tokenValid = token === cfg.WEBHOOK_TOKEN;

return [{
  json: {
    __config: cfg,
    token_valid: tokenValid,
    debug_mode: Boolean(cfg.DEBUG_MODE),
    raw_webhook: cfg.DEBUG_MODE ? body : null,
    headers,
    query,
    telnyx_signature_ed25519: headers['telnyx-signature-ed25519'] || headers['Telnyx-Signature-Ed25519'] || '',
    telnyx_timestamp: headers['telnyx-timestamp'] || headers['Telnyx-Timestamp'] || '',
    event_id: event.id || null,
    event_type: event.event_type || null,
    occurred_at: event.occurred_at || null,
    call_control_id: payload.call_control_id || null,
    call_leg_id: payload.call_leg_id || null,
    call_session_id: payload.call_session_id || null,
    connection_id: payload.connection_id || null,
    from: payload.from || null,
    to: payload.to || null,
    amd_result: payload.result || null,
    hangup_cause: payload.hangup_cause || null,
    hangup_source: payload.hangup_source || null,
    sip_hangup_cause: payload.sip_hangup_cause || null,
    client_state: payload.client_state || null,
    payload
  }
}];

const store = $getWorkflowStaticData('global');
if (!store.receiver) {
  store.receiver = {
    attempts: {},
    eventLedger: {},
    commandLedger: {},
    logs: []
  };
}

const receiver = store.receiver;
receiver.logs = receiver.logs || [];
receiver.attempts = receiver.attempts || {};
receiver.eventLedger = receiver.eventLedger || {};
receiver.commandLedger = receiver.commandLedger || {};

const cfg = $json.__config || {};
const input = $json;
const nowIso = new Date().toISOString();

const pushLog = (message, extra = {}) => {
  receiver.logs.push({ at: nowIso, message, ...extra });
  receiver.logs = receiver.logs.slice(-500);
};

if (cfg.DEBUG_MODE) {
  pushLog('Webhook received.', {
    event_type: input.event_type,
    event_id: input.event_id,
    call_control_id: input.call_control_id,
    raw: input.raw_webhook
  });
}

const dedupeKey = input.event_id || `${input.event_type || 'unknown'}::${input.call_control_id || 'no-call-control'}::${input.occurred_at || nowIso}`;
if (receiver.eventLedger[dedupeKey]) {
  pushLog('Duplicate webhook ignored.', { dedupeKey, event_type: input.event_type });
  return [{
    json: {
      __config: cfg,
      skip: true,
      reason: 'duplicate_event',
      dedupe_key: dedupeKey,
      action: 'none',
      event_type: input.event_type
    }
  }];
}
receiver.eventLedger[dedupeKey] = nowIso;

const decodeClientState = (value) => {
  if (!value) return null;
  try {
    return JSON.parse(Buffer.from(value, 'base64').toString('utf8'));
  } catch {
    return null;
  }
};

const clientState = decodeClientState(input.client_state);
const attemptKey = clientState?.attempt_id || input.call_control_id || input.call_session_id || dedupeKey;
const leadId = clientState?.lead_id || null;

if (!receiver.attempts[attemptKey]) {
  receiver.attempts[attemptKey] = {
    attempt_id: clientState?.attempt_id || attemptKey,
    lead_id: leadId,
    call_control_id: input.call_control_id || null,
    call_leg_id: input.call_leg_id || null,
    call_session_id: input.call_session_id || null,
    status: 'webhook_received',
    outcome: null,
    finalised: false,
    created_at: nowIso,
    updated_at: nowIso
  };
}

const attempt = receiver.attempts[attemptKey];
attempt.call_control_id = input.call_control_id || attempt.call_control_id || null;
attempt.call_leg_id = input.call_leg_id || attempt.call_leg_id || null;
attempt.call_session_id = input.call_session_id || attempt.call_session_id || null;
attempt.updated_at = nowIso;
attempt.last_event_type = input.event_type;
attempt.last_event_at = input.occurred_at || nowIso;

const classifyHangup = (payload) => {
  const cause = String(payload.hangup_cause || '').toLowerCase();
  const sip = String(payload.sip_hangup_cause || '');
  if (cause.includes('busy') || sip === '486') return 'busy';
  if (cause.includes('no_answer') || cause.includes('timeout') || sip === '480' || sip === '487') return 'no_answer';
  if (cause.includes('rejected') || cause.includes('blocked') || sip === '603') return 'failed';
  return 'hangup';
};

const ensureActionIdempotent = (action, reason) => {
  if (action === 'none') return { action, reason };
  const key = `${attempt.attempt_id}::${action}`;
  if (receiver.commandLedger[key]) {
    pushLog('Duplicate command suppressed.', { action, key, attempt_id: attempt.attempt_id });
    return { action: 'none', reason: `${reason || action}_already_requested` };
  }
  receiver.commandLedger[key] = {
    requested_at: nowIso,
    event_type: input.event_type,
    call_control_id: attempt.call_control_id
  };
  return { action, reason };
};

let action = 'none';
let actionReason = null;

switch (input.event_type) {
  case 'call.initiated':
    attempt.status = 'calling';
    break;

  case 'call.answered':
    attempt.status = cfg.AMD_MODE ? 'answered_pending_amd' : 'transfer_requested';
    if (!cfg.AMD_MODE) {
      attempt.outcome = 'answered_without_amd';
      action = 'transfer';
      actionReason = 'answered_without_amd';
    }
    break;

  case 'call.machine.detection.ended': {
    const result = String(input.amd_result || '').toLowerCase();
    attempt.amd_result = result;
    if (result === 'human') {
      attempt.status = 'transfer_requested';
      attempt.outcome = 'human';
      action = 'transfer';
      actionReason = 'human';
    } else if (result === 'not_sure' && Boolean(cfg.TRANSFER_ON_NOT_SURE)) {
      attempt.status = 'transfer_requested';
      attempt.outcome = 'human_not_sure';
      action = 'transfer';
      actionReason = 'human_not_sure';
    } else if (['machine', 'not_sure'].includes(result)) {
      attempt.status = 'hangup_requested';
      attempt.outcome = result === 'machine' ? 'voicemail' : 'amd_not_sure';
      attempt.finalised = true;
      action = 'hangup';
      actionReason = attempt.outcome;
    }
    break;
  }

  case 'call.machine.premium.detection.ended': {
    const result = String(input.amd_result || '').toLowerCase();
    attempt.amd_result = result;
    if (['human_residence', 'human_business'].includes(result)) {
      attempt.status = 'transfer_requested';
      attempt.outcome = result;
      action = 'transfer';
      actionReason = result;
    } else if (result === 'not_sure' && Boolean(cfg.TRANSFER_ON_NOT_SURE)) {
      attempt.status = 'transfer_requested';
      attempt.outcome = 'premium_not_sure_transfer';
      action = 'transfer';
      actionReason = 'premium_not_sure_transfer';
    } else if (['machine', 'silence', 'fax_detected', 'not_sure'].includes(result)) {
      attempt.status = 'hangup_requested';
      attempt.outcome = result === 'machine' ? 'voicemail' : result;
      attempt.finalised = true;
      action = 'hangup';
      actionReason = attempt.outcome;
    }
    break;
  }

  case 'call.machine.greeting.ended':
  case 'call.machine.premium.greeting.ended':
    attempt.last_greeting_result = String(input.amd_result || '').toLowerCase() || null;
    break;

  case 'call.bridged':
    attempt.status = 'live_transferred';
    attempt.outcome = attempt.outcome || 'human_connected';
    attempt.finalised = true;
    break;

  case 'call.hangup': {
    const outcome = classifyHangup(input.payload || {});
    attempt.status = 'hangup';
    attempt.hangup_cause = input.hangup_cause || null;
    attempt.hangup_source = input.hangup_source || null;
    if (!attempt.finalised) {
      attempt.outcome = outcome;
      attempt.finalised = true;
    }
    break;
  }

  default:
    break;
}

({ action, reason: actionReason } = ensureActionIdempotent(action, actionReason));

const actionClientState = Buffer.from(JSON.stringify({
  workflow: 'telnyx_power_dialer',
  lead_id: attempt.lead_id,
  attempt_id: attempt.attempt_id,
  action
}), 'utf8').toString('base64');

pushLog('Webhook processed.', {
  event_type: input.event_type,
  attempt_id: attempt.attempt_id,
  call_control_id: attempt.call_control_id,
  action,
  actionReason,
  outcome: attempt.outcome
});

return [{
  json: {
    __config: cfg,
    skip: false,
    dedupe_key: dedupeKey,
    event_type: input.event_type,
    action,
    action_reason: actionReason,
    action_client_state: actionClientState,
    attempt_id: attempt.attempt_id,
    lead_id: attempt.lead_id,
    call_control_id: attempt.call_control_id,
    call_leg_id: attempt.call_leg_id,
    call_session_id: attempt.call_session_id,
    attempt_status: attempt.status,
    outcome: attempt.outcome
  }
}];

const store = $getWorkflowStaticData('global');
store.receiver = store.receiver || { logs: [], attempts: {} };
const receiver = store.receiver;
const processed = $('Process Webhook State Machine').first().json;
const response = $json;
const now = new Date().toISOString();
const attemptKey = processed.attempt_id || processed.call_control_id;
const attempt = receiver.attempts[attemptKey] || {};
receiver.logs = receiver.logs || [];

attempt.updated_at = now;
attempt.transfer_command_response = response;
if ((response.data && response.data.result === 'ok') || response.result === 'ok') {
  attempt.status = 'transfer_requested';
  receiver.logs.push({ at: now, message: 'Transfer command accepted by Telnyx.', attempt_id: processed.attempt_id, call_control_id: processed.call_control_id });
} else {
  attempt.status = 'transfer_failed';
  attempt.finalised = true;
  attempt.outcome = 'transfer_failed';
  receiver.logs.push({ at: now, message: 'Transfer command failed.', attempt_id: processed.attempt_id, response });
}
receiver.logs = receiver.logs.slice(-500);
receiver.attempts[attemptKey] = attempt;

return [{ json: { ok: true, action: 'transfer', attempt_id: processed.attempt_id, call_control_id: processed.call_control_id } }];

const store = $getWorkflowStaticData('global');
store.receiver = store.receiver || { logs: [], attempts: {} };
const receiver = store.receiver;
const processed = $('Process Webhook State Machine').first().json;
const response = $json;
const now = new Date().toISOString();
const attemptKey = processed.attempt_id || processed.call_control_id;
const attempt = receiver.attempts[attemptKey] || {};
receiver.logs = receiver.logs || [];

attempt.updated_at = now;
attempt.hangup_command_response = response;
attempt.status = 'hangup_requested';
attempt.finalised = true;
receiver.logs.push({ at: now, message: 'Hangup command processed.', attempt_id: processed.attempt_id, call_control_id: processed.call_control_id, response });
receiver.logs = receiver.logs.slice(-500);
receiver.attempts[attemptKey] = attempt;

return [{ json: { ok: true, action: 'hangup', attempt_id: processed.attempt_id, call_control_id: processed.call_control_id } }];

return [{
  json: {
    ok: true,
    action: 'none',
    message: 'Webhook updated state without requiring a Telnyx command.',
    event_type: $('Process Webhook State Machine').first().json.event_type || null
  }
}];
